# ── CRUD users ────────────────────────────────────────────────────────────────
def doc_users() -> dict:
    with db.get_conn() as conn:
        rows = conn.execute("SELECT * FROM users").fetchall()
    if not rows:
        # Seed admin mặc định nếu bảng rỗng
        luu_users(ADMIN_DEFAULT)
        return ADMIN_DEFAULT.copy()
    return {
        row["username"]: {
            "ho_ten":   row["ho_ten"],
            "password": row["password"],
            "role":     row["role"],
            "pgd":      row["pgd"],
            "ngay_tao": row["ngay_tao"],
        }
        for row in rows
    }


def luu_users(u: dict):
    with db.get_conn() as conn:
        conn.execute("DELETE FROM users")
        for username, info in u.items():
            conn.execute(
                """INSERT INTO users
                   (username, ho_ten, password, role, pgd, ngay_tao)
                   VALUES (?,?,?,?,?,?)""",
                (
                    username,
                    info.get("ho_ten", ""),
                    info.get("password", ""),
                    info.get("role", "user"),
                    info.get("pgd"),
                    info.get("ngay_tao", ""),
                )
            )
        conn.commit()


def ma_hoa(pw):
    return bcrypt.hashpw(pw.encode(), bcrypt.gensalt()).decode()


def kiem_tra(pw, h):
    try:
        return bcrypt.checkpw(pw.encode(), h.encode())
    except:
        return False


def dang_nhap(un: str, pw: str):
    u = un.strip().lower()
    with db.get_conn() as conn:
        row = conn.execute(
            "SELECT * FROM users WHERE username = ?", (u,)
        ).fetchone()
    if row is None:
        db.ghi_audit(u, "login_failed", "user not found")
        return False, None
    ok = kiem_tra(pw, row["password"])
    if ok:
        db.ghi_audit(u, "login", "success")
        return True, {
            "ho_ten":   row["ho_ten"],
            "password": row["password"],
            "role":     row["role"],
            "pgd":      row["pgd"],
            "ngay_tao": row["ngay_tao"],
        }
    db.ghi_audit(u, "login_failed", "wrong password")
    return False, None


